(() => {
  'use strict';
  const $ = (s, root=document) => root.querySelector(s);
  const esc = window.escapeHTML;
  const app = $('#page-content');
  const state = { wards:[], alerts:[], metrics:[], runs:[], demo:true, summary:{}, thresholds:{low_max:.25,moderate_max:.5,high_max:.75}, files:null, filters:{}, selectedMetric:null, pollTimer:null };
  const pageMeta = {
    '/': ['Nagpur · Urban heat and exposure','Climate risk overview','Explore ward-level heat risk, street conditions, and the evidence behind each score.'],
    '/alerts':['Operations · Monitoring','Heat risk alerts','Review, filter, and acknowledge risk alerts. Simulated readings are clearly labeled.'],
    '/metrics':['Model validation · Weak supervision','Model & metrics','Measured outputs from model runs; no-run metrics remain blank rather than estimated.'],
    '/data':['Ingestion · Pipeline status','Data & pipeline','Inspect the source files and run the raster, legacy fallback, or dataset pipeline.'],
    '/settings':['Configuration · Thresholds','Settings','Configure risk thresholds and local display preferences.'],
    '/how':['Method · Explainability','How this works','Eight transparent stages connect data ingestion to ward-level decisions.']
  };
  const riskBadge = level => `<span class="badge badge-${esc(String(level||'moderate').toLowerCase())}">${esc(level||'Unclassified')}</span>`;
  const demoBadge = () => '<span class="badge badge-demo">DEMO DATA</span>';
  const showVal = (v,d=2) => num(v,d);
  const card = (title, body, subtitle='') => `<section class="card"><div class="card-header"><div><h2 class="card-title">${title}</h2>${subtitle?`<p class="card-subtitle">${subtitle}</p>`:''}</div></div>${body}</section>`;
  const table = (headers, rows) => `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows||''}</tbody></table></div>`;
  function confusionTable(matrix, labels = []) {
    const names = labels.length ? labels : matrix.map((_, index) => `Class ${index + 1}`);
    const values = matrix.flat().map(value => Number(value) || 0);
    const max = Math.max(1, ...values);
    const shade = value => {
      const ratio = (Number(value) || 0) / max;
      return ratio >= .75 ? '#93C5FD' : ratio >= .5 ? '#BFDBFE' : ratio >= .25 ? '#DBEAFE' : '#F8FAFC';
    };
    const head = names.map(name => `<th scope="col">Predicted ${esc(name)}</th>`).join('');
    const body = matrix.map((row, index) => `<tr><th scope="row">Actual ${esc(names[index] || `Class ${index + 1}`)}</th>${row.map(value => `<td style="background:${shade(value)}" aria-label="${Number(value) || 0} records">${Number(value) || 0}</td>`).join('')}</tr>`).join('');
    return `<div class="table-wrap confusion-wrap"><table class="confusion-table"><caption class="sr-only">Confusion matrix: rows are actual classes, columns are predicted classes. Values are recorded sample counts.</caption><thead><tr><th scope="col">Actual / predicted</th>${head}</tr></thead><tbody>${body}</tbody></table></div>`;
  }
  const noRows = (text='No records returned by the API.') => `<tr><td colspan="12"><div class="empty-state">${esc(text)}</div></td></tr>`;
  const isDemoSource=value=>/demo|synthetic/i.test(String(value||''));
  function setMeta(route) { const m=pageMeta[route]||['Ward details · Explainable risk','Ward detail','Review scores, trend, and evidence.']; $('#page-eyebrow').textContent=m[0];$('#page-title').textContent=m[1];$('#page-description').textContent=m[2];$('#heading-actions').innerHTML=route==='/'?'<button class="btn" type="button" data-action="refresh">↻ <span>Refresh</span></button><button class="btn btn-primary" type="button" data-action="export-csv">⇩ <span>Export CSV</span></button><button class="btn" type="button" data-action="export-pdf">⇩ <span>Export PDF</span></button>':route==='/alerts'?'<button class="btn" type="button" data-action="export-alerts">⇩ <span>Export CSV</span></button><button class="btn btn-primary" type="button" data-action="simulate">＋ <span>Simulate breach</span></button>':route==='/data'?'<button class="btn" type="button" data-action="refresh">↻ <span>Refresh data</span></button>':'';document.title=`GeoCool | ${m[1]}`;document.querySelectorAll('[data-route]').forEach(a=>{const current=a.dataset.route===route||(route.startsWith('/ward/')&&a.dataset.route==='/');if(current)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');}); }
  function updateDemo(demo) { state.demo=demo!==false; const badge=$('#data-provenance'), notice=$('#demo-notice');badge.textContent=state.demo?'DEMO DATA':'LIVE DATA';badge.className=`badge ${state.demo?'badge-demo':'badge-success'}`;badge.setAttribute('aria-label',state.demo?'DEMO DATA: seeded or synthetic values':'Live data');notice.classList.toggle('hidden',!state.demo); }
  async function loadOverview() { try { const x=await GeoAPI.get('/api/wards'); state.overviewError=null;state.wards=x.wards||[];state.summary=x.summary||{};updateDemo(x.demo??true);return x; } catch(e){ state.overviewError=e;throw e; } }
  async function loadAlerts() { try {const x=await GeoAPI.get('/api/alerts');state.alertError=null;state.alerts=x.alerts||[];if(x.demo!==undefined)updateDemo(x.demo);return x;}catch(e){state.alertError=e;throw e;} }
  function renderDashboard() {
    const s=state.summary||{}, active=state.alerts.filter(a=>!['resolved','closed'].includes(String(a.status).toLowerCase())).length;
    const critical=s.critical_count ?? state.wards.filter(w=>String(w.risk_class).toLowerCase()==='critical').length;
    const f1=state.metrics.find(m=>m.f1!==null&&m.f1!==undefined)?.f1;
    const cards=[['Wards Monitored',s.ward_count??state.wards.length,'Filter all wards','all'],['Critical Wards',critical,'Filter critical wards','critical'],['Active Alerts',s.active_alerts??active,'View open alerts','alerts'],['Last Refresh',s.last_refresh?new Date(s.last_refresh).toLocaleString():'—','Latest API refresh','refresh'],['Model F1',f1==null?'—':showVal(f1),'Only from a recorded run','metrics']];
    const kpis=cards.map(([label,value,meta,filter])=>`<button class="kpi-card" type="button" data-kpi="${filter}" aria-label="${label}: ${esc(value)}. ${meta}"><span class="kpi-mark"></span><span class="kpi-label">${label}</span><strong class="kpi-value">${esc(value)}</strong><span class="kpi-meta">${meta} ${state.demo?'<b>· DEMO DATA</b>':''}</span></button>`).join('');
    const rows=wardRows();
    const mapSection=`<section class="card map-card"><div class="map-toolbar"><div class="search-wrap"><span class="search-icon" aria-hidden="true">⌕</span><input class="input" id="ward-search" type="search" placeholder="Search ward or edge ID" aria-label="Search ward or edge ID"><button class="btn btn-small" type="button" data-action="search-map">Search</button></div><div class="layer-menu" role="group" aria-label="Map layer">${['Risk Class','LST','NDVI','Slope','Population','AHP Suitability','Street-level'].map((n,i)=>`<button type="button" class="layer-button" data-layer="${n}" aria-pressed="${i===0}">${n}</button>`).join('')}</div><label class="form-field" style="display:flex;align-items:center;gap:6px"><span>View</span><select class="select" id="map-mode" aria-label="Map view"><option value="ward">Ward</option><option value="street">Street</option></select></label></div><div id="risk-map" class="map-canvas" role="region" aria-label="Nagpur ward risk map"></div><div class="map-footer"><div class="map-legend" aria-label="Risk legend">${['low','moderate','high','critical'].map(x=>`<span class="legend-item"><i class="legend-swatch ${x}" aria-hidden="true"></i>${x[0].toUpperCase()+x.slice(1)}</span>`).join('')}</div><span class="map-attribution"><span data-basemap-provider>Loading map base layer…</span> · Ward outlines</span></div></section>`;
    const byRisk=['Critical','High','Moderate','Low'].map(level=>{const count=state.wards.filter(w=>String(w.risk_class).toLowerCase()===level.toLowerCase()).length;return `<div class="risk-row"><span class="risk-label">${level}</span><span class="risk-track"><span class="risk-fill" style="display:block;width:${state.wards.length?Math.round(count/state.wards.length*100):0}%;background:${({Critical:'#FEE2E2',High:'#FFEDD5',Moderate:'#FEF9C3',Low:'#DCFCE7'})[level]}"></span></span><strong class="risk-count">${count}</strong></div>`;}).join('');
    const tableCard=card('Ward risk register',`<div class="table-tools"><label class="form-field"><span>Show</span><select class="select" id="ward-filter" aria-label="Filter wards"><option value="all">All wards</option><option value="critical">Critical only</option><option value="high">High and critical</option></select></label></div>${table(['Ward','ML class','AHP class','ML risk','AHP risk','Mean risk','P90 risk','Edges',''],rows)}`,'Scores are risk estimates; AHP score is inverted from suitability. DEMO DATA is synthetic.');
    app.innerHTML=`<div class="kpi-grid">${kpis}</div><div class="dashboard-grid">${mapSection}<div class="side-stack">${card('Primary risk-class distribution',`<div class="risk-list">${byRisk}</div>`,`Uses ML when available; AHP is the reference class · ${state.demo?'DEMO DATA':''}`)}${card('Explainability & caveats',`<div class="explanation"><p><strong>AHP inversion:</strong> AHP stores suitability, where higher is cooler/better. Displayed AHP risk is <code>1 − suitability</code>. Labels are weak supervision, not field ground truth.</p></div><p class="form-help" style="margin-top:12px">Particulate matter (PM) is a constant placeholder (65.0), not a sensor measurement. It must not be interpreted as a measured risk driver.</p><a class="btn btn-small" href="/how" data-route="/how">Methodology and glossary</a></div>`)} </div><div id="ward-register" style="margin-top:16px">${tableCard}</div>`;
    if(window.GeoMap) GeoMap.init('#risk-map',state.wards,w=>navigate(`/ward/${encodeURIComponent(w.ward_id)}`));
    if(state.overviewError) app.insertAdjacentHTML('afterbegin',`<div class="data-notice" role="alert">Ward API unavailable: ${esc(state.overviewError.message)}. Retry with Refresh; other routes remain available.</div>`);
    if(!state.wards.length&&!state.overviewError) $('#risk-map').insertAdjacentHTML('beforeend','<p class="empty-state">No ward geometry returned. Map will populate when the API provides ward polygons.</p>');
  }
  function wardRows(filter='all') { const rows=state.wards.filter(w=>filter==='all'||(filter==='critical'?String(w.risk_class).toLowerCase()==='critical':filter==='high'?['critical','high'].includes(String(w.risk_class).toLowerCase()):true));return rows.length?rows.map(w=>`<tr><td><a href="/ward/${encodeURIComponent(w.ward_id)}" data-route="/ward/${encodeURIComponent(w.ward_id)}">${esc(w.name||w.ward_id)}</a><div class="form-help">${esc(w.ward_id)}</div>${isDemoSource(w.provenance)?demoBadge():''}</td><td>${w.ml_class?riskBadge(w.ml_class):'—'}</td><td>${w.ahp_class?riskBadge(w.ahp_class):'—'}</td><td>${showVal(w.ml_score)}</td><td>${showVal(w.ahp_score)}</td><td>${showVal(w.mean_risk)}</td><td>${showVal(w.p90_risk)}</td><td>${w.edge_count??'—'}</td><td><button class="btn btn-small" type="button" data-open-ward="${esc(w.ward_id)}">Details</button></td></tr>`).join(''):noRows(state.overviewError?'Ward records unavailable.':'No wards match this filter.'); }
  async function renderWard(id) {
    app.innerHTML='<div class="empty-state">Loading ward details…</div>';
    const known=state.wards.find(w=>String(w.ward_id)===String(id));let ward=known, streets=[], history=[], explain=null, error=null;
    try { const result=await Promise.allSettled([GeoAPI.get(`/api/wards/${encodeURIComponent(id)}`),GeoAPI.get(`/api/wards/${encodeURIComponent(id)}/streets`),GeoAPI.get(`/api/wards/${encodeURIComponent(id)}/sensor-history`),GeoAPI.get(`/api/explain/${encodeURIComponent(id)}`)]);if(result[0].status==='fulfilled')ward=result[0].value;else error=result[0].reason;if(result[1].status==='fulfilled')streets=result[1].value.streets||result[1].value.edges||result[1].value||[];if(result[2].status==='fulfilled')history=result[2].value.history||result[2].value.readings||result[2].value||[];if(result[3].status==='fulfilled')explain=result[3].value;} catch(e){error=e;}
    if(!ward){app.innerHTML=`<div class="data-notice" role="alert">Ward ${esc(id)} could not be loaded${error?`: ${esc(error.message)}`:''}. <a href="/" data-route="/">Return to overview</a>.</div>`;return;}
    const wardIsDemo=ward.demo===true||isDemoSource(ward.provenance);setMeta(`/ward/${id}`);const causes=explain?.explanation||ward.explanation||'Model evidence has not been returned for this ward. No explanation is inferred.';const contributions=explain?.contributions||[];const top=[...contributions].sort((a,b)=>Math.abs(Number(b.contribution)||0)-Math.abs(Number(a.contribution)||0)).slice(0,3);
    const contributionMarkup=top.length?`<div class="contribution-list">${top.map(c=>{const val=Number(c.contribution)||0;return `<div class="contribution-row"><span class="contribution-name">${esc(c.feature)}</span><span class="contribution-track"><span class="contribution-bar ${val<0?'negative':''}" style="display:block;width:${Math.max(3,Math.min(100,Math.abs(val)*100))}%"></span></span><span class="contribution-value">${val>0?'+':''}${num(val,3)}</span></div>`;}).join('')}</div><div class="chart-wrap" style="height:190px;max-width:100%"><canvas id="ward-contrib-chart" aria-label="Top three feature contribution chart"></canvas></div>`:'<p class="empty-state">No feature contributions returned by /api/explain for this ward.</p>';
    const weights=explain?.weights||{lst:.35,ndvi:.25,pm:.20,population:.10,slope:.10};const weightRows=Object.entries(weights).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${num(v,2)}</td></tr>`).join('')||noRows('AHP weights are not available from the API.');
    const alerts=state.alerts.filter(a=>String(a.ward_id)===String(id));
    app.innerHTML=`<div class="heading-actions" style="justify-content:flex-start;margin-bottom:14px"><button class="btn" type="button" data-action="zoom-ward" data-id="${esc(id)}">Zoom to ward</button><button class="btn" type="button" data-action="view-streets" data-id="${esc(id)}">View streets (${streets.length})</button><button class="btn" type="button" data-action="sensor-history" data-id="${esc(id)}">View sensor history (${history.length})</button><a class="btn" href="/alerts" data-route="/alerts">Alerts (${alerts.length})</a></div>${error?`<div class="data-notice">Some detail endpoints are unavailable: ${esc(error.message)}</div>`:''}<div class="content-grid-4">${[['ML risk score',ward.ml_score],['ML class',ward.ml_class||'No ML prediction'],['AHP risk (1 − suitability)',ward.ahp_score],['AHP class',ward.ahp_class||'—']].map(([label,val])=>`<div class="metric-card"><span class="metric-label">${label}</span><strong class="metric-value">${typeof val==='number'?num(val):esc(val||'—')}</strong>${wardIsDemo?demoBadge():''}</div>`).join('')}</div><p class="form-help">Primary class basis: ${esc(ward.class_basis||'AHP-derived weak label')}. AHP class is displayed separately as the reference.</p><div class="content-grid-2" style="margin-top:16px"><div class="section-stack">${card(`Why ${esc(ward.name||id)} is classified ${esc(ward.risk_class||'')}`,`<div class="explanation"><p>${esc(causes)}</p></div><h3 class="card-title" style="margin:15px 0 9px">Top three signed contributions ${wardIsDemo?'<span class="badge badge-demo">DEMO DATA</span>':''}</h3>${contributionMarkup}<p class="form-help">Positive/negative values show direction of model contribution. DEMO DATA if seeded.</p><div class="data-notice" style="margin-top:12px"><div><span class="badge badge-warning">WEAK-LABEL</span> <strong>Weak supervision:</strong> Labels are derived from AHP-inverted risk thresholds, not field ground truth. ${explain?.weak_label?esc(explain.weak_label):''}</div></div>${explain?.constant_inputs?.pm?.constant===true?`<div class="data-notice"><div><span class="badge badge-warning">CONSTANT INPUT · PM ${Number(explain.constant_inputs.pm.value??65).toFixed(1)}</span> PM is a constant placeholder, not a measurement; it cannot discriminate observations.</div></div>`:`<div class="data-notice"><div><span class="badge badge-warning">PM INPUT LIMIT</span> PM is a constant placeholder, not a measured input.</div></div>`}`,'Explanation uses API contributions only; no values are fabricated.')}${card('Causes & precautions',`<p>${esc(ward.cause||'Potential contributors include heat exposure, vegetation, population, and terrain; verify with local field teams.')}</p><p>${esc(ward.precaution||'Prioritize shade and hydration access; confirm conditions with on-the-ground measurements.')}</p><div class="table-actions"><button class="btn btn-small" type="button" data-action="ward-alert-status" data-status="ack" data-id="${esc(id)}">Acknowledge alert</button><button class="btn btn-small btn-danger" type="button" data-action="ward-alert-status" data-status="resolved" data-id="${esc(id)}">Resolve alert</button></div>`,'Precautions are operational guidance, not a diagnosis.')}</div><div class="section-stack">${card('Sensor history trend',`${history.some(item=>isDemoSource(item.provenance))?'<span class="badge badge-demo">DEMO DATA · SENSOR HISTORY</span>':''}<div class="chart-wrap" style="height:190px;max-width:100%"><canvas id="ward-history-chart" aria-label="Sensor history trend chart"></canvas></div>${history.length?'<p class="form-help">Trend derived from sensor history returned by the API.</p>':'<p class="empty-state">No sensor history available for this ward.</p>'}`)}${card('AHP weights',table(['Factor','Weight'],weightRows),'<strong>AHP suitability</strong> is cooler/better when higher; displayed AHP risk = 1 − suitability.')}${card('Street edges',streets.length?table(['Edge','LST','NDVI','Slope','Population','PM'],streets.slice(0,20).map(e=>`<tr data-edge-row="${esc(e.edge_id||'')}"><td>${esc(e.edge_id||'—')}</td><td>${showVal(e.lst,1)}</td><td>${showVal(e.ndvi,3)}</td><td>${showVal(e.slope,2)}</td><td>${showVal(e.population,1)}</td><td>${showVal(e.pm,1)}*</td></tr>`).join('')):'<p class="empty-state">No street records returned. Use View streets to retry.</p>','*PM is a constant placeholder, not a sensor measurement.')}</div></div>`;
    if(top.length&&window.GeoCharts)GeoCharts.contribution('#ward-contrib-chart',top);if(history.length&&window.GeoCharts)GeoCharts.sparkline('#ward-history-chart',history,history[0].temperature!==undefined?'temperature':'ml_score');const focusedEdge=new URLSearchParams(location.search).get('edge');if(focusedEdge){const row=[...app.querySelectorAll('[data-edge-row]')].find(item=>item.dataset.edgeRow===focusedEdge);if(row){row.classList.add('focused-row');row.scrollIntoView({behavior:'smooth',block:'center'});}}
  }
  async function renderAlerts() {
    try {await loadAlerts();}catch(e){}
    const wards=[...new Set(state.alerts.map(a=>a.ward_id).filter(Boolean))];
    app.innerHTML=`${state.alertError?`<div class="data-notice" role="alert">Alerts API unavailable: ${esc(state.alertError.message)}</div>`:''}<section class="card"><div class="card-header"><div><h2 class="card-title">Alert register ${state.demo?demoBadge():''}</h2><p class="card-subtitle">Simulated sensor alerts are synthetic and do not represent official heat warnings.</p></div><button class="btn" type="button" data-action="export-alerts">Export alerts CSV</button></div><div class="form-grid" style="margin-bottom:14px"><label class="form-field"><span>Ward</span><select id="alert-ward-filter" class="select"><option value="all">All wards</option>${wards.map(w=>`<option>${esc(w)}</option>`).join('')}</select></label><label class="form-field"><span>Risk class</span><select id="alert-class-filter" class="select"><option value="all">All classes</option>${['critical','high','moderate','low'].map(v=>`<option value="${v}">${v}</option>`).join('')}</select></label><label class="form-field"><span>Status</span><select id="alert-status-filter" class="select"><option value="all">All statuses</option><option value="open">Open</option><option value="ack">Acknowledged</option><option value="resolved">Resolved</option></select></label><label class="form-field"><span>Since</span><select id="alert-time-filter" class="select"><option value="all">Any time</option><option value="24">Last 24 hours</option><option value="168">Last 7 days</option></select></label></div><div id="alerts-table"></div></section><div class="content-grid-2" style="margin-top:16px">${card('Simulate threshold breach',`<p>A synthetic sensor reading will be submitted to the API. It is not a physical sensor alert.</p><div class="form-grid"><label class="form-field"><span>Ward</span><select id="simulate-ward" class="select">${state.wards.map(w=>`<option value="${esc(w.ward_id)}">${esc(w.name||w.ward_id)}</option>`).join('')}</select></label><label class="form-field"><span>Temperature threshold (°C)</span><input id="simulate-threshold" class="input" type="number" min="30" max="60" step=".5" value="40"></label></div><button class="btn btn-primary" style="margin-top:12px" type="button" data-action="simulate">Simulate demo breach</button>`)}${card('Alert notes','<p>Alert classification and timestamps are returned from the API. Use acknowledge or resolve to persist a status update.</p>')}</div>`;
    if(new URLSearchParams(location.search).get('status')==='open')$('#alert-status-filter').value='open';
    renderAlertTable();
  }
  function renderAlertTable() {
    const val=id=>$(id)?.value||'all', ward=val('#alert-ward-filter'), risk=val('#alert-class-filter'), status=val('#alert-status-filter'), hrs=val('#alert-time-filter');
    const list=state.alerts.filter(a=>(ward==='all'||String(a.ward_id)===ward)&&(risk==='all'||String(a.severity||a.risk_class).toLowerCase()===risk)&&(status==='all'||String(a.status).toLowerCase()===status)&& (hrs==='all'||(Date.now()-new Date(a.ts||a.created_at).getTime())<=Number(hrs)*3600000));
    const rows=list.map(a=>`<tr><td>${esc(a.ts?new Date(a.ts).toLocaleString():'—')} ${isDemoSource(a.provenance)?demoBadge():''}</td><td><a href="/ward/${encodeURIComponent(a.ward_id)}" data-route="/ward/${encodeURIComponent(a.ward_id)}">${esc(a.ward_name||a.ward_id||'—')}</a></td><td>${riskBadge(a.severity||a.risk_class)}</td><td>${esc(a.cause||'—')}<div class="form-help">${esc(a.precaution||'')}</div></td><td>${esc(a.status||'open')}</td><td><div class="table-actions"><button class="btn btn-small" data-action="alert-status" data-id="${esc(a.id)}" data-status="ack">Acknowledge</button><button class="btn btn-small btn-danger" data-action="alert-status" data-id="${esc(a.id)}" data-status="resolved">Resolve</button></div></td></tr>`).join('');
    $('#alerts-table').innerHTML=table(['Time','Ward','Class','Cause / precaution','Status','Actions'],rows||noRows('No alerts match these filters.'));
  }
  async function renderMetrics() {
    let payload={};try{payload=await GeoAPI.get('/api/metrics');state.metricError=null;state.metrics=payload.metrics||[];state.runs=payload.model_runs||[];updateDemo(payload.demo??state.demo);}catch(e){state.metricError=e;}
    const latestByAlgo=new Map();for(const run of state.metrics){const key=String(run.algo||run.algorithm||'Model');if(!latestByAlgo.has(key))latestByAlgo.set(key,run);}
    const metrics=[...latestByAlgo.values()].map(m=>{
      const title=esc(m.algo||'Model');
      if(m.available===false||m.status==='unavailable')return `<section class="card"><div class="card-header"><div><h2 class="card-title">${title}</h2><p class="card-subtitle">${isDemoSource(m.provenance)?demoBadge():''} · latest attempt</p></div><span class="badge badge-warning">UNAVAILABLE</span></div><div class="data-notice" role="alert"><strong>No scores were produced.</strong> ${esc(m.error||'Inspect the training log for this model attempt.')}</div></section>`;
      const validation=m.validation?.split?`Holdout: ${m.validation.split}`:'Holdout details unavailable';
      const cv=m.kfold?.available?` · ${m.kfold.folds||'Group'}-fold evaluation available`:m.kfold?` · k-fold unavailable: ${m.kfold.reason||m.kfold.message||'insufficient groups/classes'}`:'';
      const balance=m.class_balance_policy?`Class balance: ${m.class_balance_policy}.`:'';
      return `<section class="card"><div class="card-header"><div><h2 class="card-title">${title}</h2><p class="card-subtitle">${isDemoSource(m.provenance)?demoBadge():''} ${esc(m.provenance||'API metrics')}</p></div></div><p class="form-help">${esc(validation+cv)}. ${esc(balance)}</p><div class="content-grid-3">${['accuracy','precision','recall','f1','rmse','mae','r2'].map(k=>`<div class="metric-card"><span class="metric-label">${k.toUpperCase()}</span><strong class="metric-value">${m[k]===null||m[k]===undefined?'—':showVal(m[k],3)}</strong>${isDemoSource(m.provenance)?'<span class="badge badge-demo">DEMO DATA</span>':''}</div>`).join('')}</div>${m.confusion_matrix?.length?`<h3 class="card-title" style="margin-top:14px">Confusion matrix</h3><p class="form-help">Rows are actual classes; columns are predicted classes. Cell values are record counts; dark text is retained on every heatmap fill.</p>${confusionTable(m.confusion_matrix,m.confusion_labels||m.classes||[])}`:'<p class="empty-state">No confusion matrix returned for this run.</p>'}${m.per_class?`<details><summary>Per-class metrics</summary><pre>${esc(JSON.stringify(m.per_class,null,2))}</pre></details>`:''}</section>`;
    }).join('');
    const runs=state.runs.length?table(['Run','Algorithm','Created','F1','Status','Compare'],state.runs.map((r,i)=>`<tr><td>${esc(r.id||r.run_id||`Run ${i+1}`)} ${isDemoSource(r.provenance)?demoBadge():''}</td><td>${esc(r.algo||r.algorithm||'—')}</td><td>${esc(r.created_at?new Date(r.created_at).toLocaleString():'—')}</td><td>${r.f1==null?'—':showVal(r.f1,3)}</td><td>${esc(r.status||'complete')}</td><td><input type="checkbox" class="run-compare" value="${esc(r.id||r.run_id||i)}" aria-label="Compare run ${i+1}"></td></tr>`).join('')):'<div class="empty-state">No model runs yet.</div>';
    app.innerHTML=`${state.metricError?`<div class="data-notice" role="alert">Metrics API unavailable: ${esc(state.metricError.message)}</div>`:''}<div class="data-notice" role="note"><div><strong>Weak supervision:</strong> target classes are generated from thresholds applied to AHP-inverted risk. These are not field ground truth. Metrics only appear when returned from a recorded model run.</div></div><div class="section-stack" style="margin-top:16px">${metrics||'<div class="empty-state">No model metrics are available. Train a model to record a run; no placeholder numbers are shown.</div>'}</div><div class="content-grid-2" style="margin-top:16px">${card('Train / experiment',`<form id="experiment-form" class="form-grid"><label class="form-field"><span>Holdout test ratio</span><input class="input" name="split_ratio" type="number" min=".1" max=".4" step=".05" value=".2" required></label><label class="form-field"><span>Folds</span><input class="input" name="folds" type="number" min="2" max="10" step="1" value="5" required></label><label class="form-field"><span>Random seed</span><input class="input" name="seed" type="number" value="42" required></label><label class="form-field"><span>Experiment note</span><input class="input" name="note" maxlength="100" placeholder="Optional label"></label><button class="btn btn-primary" type="button" data-action="train-model">Train model</button><button class="btn" type="button" data-action="experiment">Run experiment</button></form><button class="btn" style="margin-top:10px" type="button" data-action="predict">Predict current wards</button>`,'Metrics will be shown only after a successful API response.')}${card('Compare model runs',`${runs}<button class="btn btn-small" type="button" data-action="compare-runs" style="margin-top:10px">Compare selected runs</button><div id="run-comparison" aria-live="polite"></div>`,'Select two or more persisted runs. DEMO DATA remains labeled.')}</div>`;
  }
  async function renderData() {
    let files=null,health=null,jobs=null,error=null;const started=performance.now();
    try{files=await GeoAPI.get('/api/data/files');state.files=files;updateDemo(files.demo??state.demo);}catch(e){error=e;}
    try{health=await GeoAPI.get('/api/health');}catch(e){health={error:e.message};}
    try{jobs=await GeoAPI.get('/api/pipeline/jobs');}catch(e){jobs=null;}
    const rasters=files?.rasters||[];const rasterRows=rasters.map(r=>`<tr><td>${esc(r.name||r.path)}</td><td>${esc(r.status||(r.exists?'Present':'Missing'))}</td><td>${r.size==null?'—':esc(r.size)}</td><td>${r.modified?esc(new Date(r.modified).toLocaleString()):'—'}</td><td>${esc(r.producer||r.script||'—')}</td></tr>`).join('')||noRows('Raster inventory was not returned by the API.');
    const columns=files?.columns||files?.csv_preview?.columns||[];let preview=files?.csv_preview;let rows=Array.isArray(preview)?preview:(preview?.rows||[]);if(!Array.isArray(rows))rows=[];
    const csv=columns.length?table(columns.slice(0,12),rows.slice(0,50).map(row=>`<tr>${columns.slice(0,12).map(c=>`<td>${esc(row[c]??'—')}</td>`).join('')}</tr>`).join('')||noRows('CSV file contains no preview rows.')):'<div class="empty-state">No CSV preview is available.</div>';
    app.innerHTML=`${error?`<div class="data-notice" role="alert">Data API unavailable: ${esc(error.message)}</div>`:''}<div class="content-grid-2">${card('Source raster inventory',table(['GeoTIFF','Status','Size','Modified','Producer'],rasterRows),`Expected sources are four GeoTIFFs; ${rasters.length} listed by API.`)}${card('CSV dataset preview',`${files?.row_count==null?'Row count unavailable':`<p><strong>${esc(files.row_count)}</strong> rows · first 50 records below</p>`}<p><strong>Columns:</strong> ${columns.length?columns.map(esc).join(', '):'—'}</p>${csv}<p class="badge badge-warning">PM=65.0 is a constant placeholder; not measured data.</p>`,'CSV values are returned by /api/data/files.')}</div><div class="content-grid-2" style="margin-top:16px">${card('Pipeline jobs',`<p>Start a job to stream progress. GEE authorization or export limits can affect raster results.</p><div class="job-row"><button class="btn btn-primary" type="button" data-action="pipeline" data-pipeline="raster">Download rasters (Earth Engine)</button><button class="btn" type="button" data-action="pipeline" data-pipeline="java">Fallback download (Java)</button><button class="btn" type="button" data-action="pipeline" data-pipeline="dataset">Rebuild dataset</button><button class="btn" type="button" data-action="pipeline" data-pipeline="model">Train and predict</button></div><p class="badge badge-warning">Java downloader is a legacy 5 km fallback and not the canonical ROI. Use only if the Python Earth Engine raster pipeline is unavailable.</p><div id="job-list">${renderJobs(jobs)}</div><div id="pipeline-console" class="console" role="log" aria-live="polite" aria-label="Live pipeline log"><div class="console-line">${new Date().toLocaleTimeString()} · Ready. Start a pipeline job to view live logs.</div></div>`)}${card('Service health',`<p>API latency: <strong>${esc(health?.latency_ms??Math.round(performance.now()-started))} ms</strong> (server health response)</p><p>Database: <strong>${esc(health?.database?.connected===true?'Connected':health?.database?.connected===false?'Unavailable':'Unknown')}</strong> · ${esc(health?.database?.engine||'')}</p><p>Raster status: <strong>${esc(health?.rasters?.present_count??rasters.filter(r=>r.exists).length)} of ${esc(health?.rasters?.total??rasters.length)} present</strong></p><p>Model files: <strong>${esc(health?.model_files?.count??'Status not reported')}</strong></p><p>Earth Engine authorization: <strong>${esc(health?.earth_engine_auth?.status??health?.earth_engine??'Not reported')}</strong></p><button class="btn btn-small" type="button" data-action="health-check">Check health again</button>`,'Any health failure should be resolved in the service environment; credentials are never exposed in this UI.')}</div>`;
    if(Array.isArray(files?.rasters)&&files.rasters.some(r=>r.provenance))$('#data-provenance').textContent='DEMO DATA';
  }
  function renderJobs(jobs){const list=Array.isArray(jobs)?jobs:(jobs?.jobs||[]);return list.length?`<div class="section-stack" style="margin:12px 0">${list.map(j=>`<div class="job-row"><strong>${esc(j.job_id||j.id)}</strong><span class="job-status">${esc(j.state||j.status||'queued')}</span><span>${esc(j.pipeline||j.type||'')}</span></div>`).join('')}</div>`:'<p class="empty-state">No pipeline jobs are listed.</p>';}
  async function renderSettings() {
    try{const x=await GeoAPI.get('/api/settings/thresholds');state.thresholds=x.thresholds||x;}catch(e){state.thresholdError=e;}
    const t=state.thresholds||{};
    app.innerHTML=`${state.thresholdError?`<div class="data-notice">Threshold service unavailable: ${esc(state.thresholdError.message)}. Defaults shown only as controls; not saved.</div>`:''}<div class="content-grid-2">${card('Risk thresholds',`<form id="threshold-form" class="section-stack">${[['low_max','Low maximum'],['moderate_max','Moderate maximum'],['high_max','High maximum']].map(([k,label])=>`<label class="form-field"><span>${label}: <output id="out-${k}">${num(t[k],2)}</output></span><input class="input threshold-range" type="range" min="0.05" max="0.95" step="0.01" name="${k}" value="${Number(t[k]??0.25)}" aria-label="${label}"></label>`).join('')}<p class="form-help">Thresholds classify AHP-inverted risk (risk = 1 − suitability). Saving may reclassify existing scores through the API.</p><button class="btn btn-primary" type="submit">Save thresholds and reclassify</button></form>`)}${card('Display and refresh',`<div class="section-stack"><label class="form-field"><span>Theme</span><select class="select" id="theme-choice"><option value="light">Light</option><option value="dark">Dark</option></select></label><label class="form-field"><span>Refresh interval</span><select class="select" id="refresh-interval"><option value="0">Manual only</option><option value="1">Every minute</option><option value="5">Every 5 minutes</option><option value="15">Every 15 minutes</option></select></label><label class="form-field" style="display:flex;align-items:center;gap:8px"><input id="demo-mode-toggle" type="checkbox" ${state.demo?'checked':''}><span>Demo Mode</span></label><p class="form-help">PUT /api/settings/demo-mode changes the persistent mode preference only; synthetic records remain marked DEMO DATA and are never converted to measured data.</p><button class="btn" type="button" data-action="contrast-audit">Run contrast audit</button><p id="contrast-result" data-contrast-result aria-live="polite">Audit checks visible foreground/background text pairs against WCAG AA.</p></div>`)}${card('Data interpretation',`<div class="data-notice"><div><strong>AHP inversion:</strong> AHP score represents suitability (higher is better/cooler); risk = 1 − suitability. Model target labels are weak supervision. PM=65.0 is a placeholder, not a measured input.</div></div>`,'Synthetic values remain DEMO DATA even if the notice is hidden.')}</div>`;
    $('#theme-choice').value=document.documentElement.dataset.theme||'light';$('#refresh-interval').value=localStorage.getItem('geocoolRefresh')||'0';
  }
  function renderHow() {
    const stages=[['1 · Source data','Earth Engine GeoTIFFs and street-edge CSV','scripts/1_download_rasters.py · /api/pipeline/raster'],['2 · Legacy fallback','Optional Java downloader (5 km legacy radius)','scripts/GisImageDownloader.java · /api/pipeline/java'],['3 · Dataset construction','Sample raster values at street edges; preserve geometry','scripts/2_build_real_dataset.py · /api/pipeline/dataset'],['4 · Ward aggregation','Aggregate edge risk into ward summaries','GET /api/wards/{ward_id}/streets'],['5 · AHP suitability','Weighted multi-criteria suitability score','composite_suitability_score · /api/wards'],['6 · Risk classification','Invert AHP suitability, then apply thresholds','risk = 1 − suitability · PUT /api/settings/thresholds'],['7 · ML validation','Train and evaluate against AHP-derived weak labels','POST /api/model/train · GET /api/metrics'],['8 · Explanation & alerts','Feature contributions, sensor history, alert workflow','GET /api/explain/{ward_id} · /api/alerts']];
    const glossary=[['LST','Land Surface Temperature from raster data.'],['NDVI','Normalized Difference Vegetation Index; vegetation signal.'],['HRI','Heat Risk Index; derived score/classification in this prototype.'],['AHP','Analytic Hierarchy Process; here it produces a suitability score, inverted for risk.'],['RMSE','Root Mean Squared Error; regression error measure.'],['F1','Harmonic mean of precision and recall.'],['Weak supervision','Labels generated from rules or proxy scores rather than verified field ground truth.']];
    app.innerHTML=`<div class="data-notice"><div><strong>Prototype limitations:</strong> Seeded data and metrics are DEMO DATA, not official NMC or satellite observations. PM is a constant placeholder. AHP-derived labels are not field ground truth.</div></div><div class="content-grid-2" style="margin-top:16px">${card('Eight-stage methodology',`<ol class="stage-list">${stages.map(([name,desc,source])=>`<li style="padding:10px 0;border-bottom:1px solid var(--border)"><strong>${name}</strong><p>${desc}</p><code>${esc(source)}</code></li>`).join('')}</ol>`)}${card('Glossary',table(['Term','Meaning'],glossary.map(([a,b])=>`<tr><th scope="row">${a}</th><td>${b}</td></tr>`).join('')))}${card('AHP weights',`<p>Default AHP weights: LST 0.35, NDVI 0.25, PM 0.20, population 0.10, slope 0.10. Ward-specific weights returned by the API take precedence.</p><p><strong>Interpretation:</strong> suitability higher means cooler/better; invert suitability for risk. PM is a constant placeholder, not a measurement.</p>`)}${card('Model interpretation',`<p>Accuracy, precision, recall, F1, RMSE, MAE, R², and confusion matrices are shown only when produced by a model run. No-run values display an em dash.</p><p>Contributions explain model behavior, not causal proof. Verify any planning action with local observation and subject-matter review.</p>`)}</div>`;
  }
  async function navigate(path, push=true) {
    if(push){const currentTheme=new URLSearchParams(location.search).get('theme');if(currentTheme&&!path.includes('theme='))path+=`${path.includes('?')?'&':'?'}theme=${encodeURIComponent(currentTheme)}`;history.pushState({},'',path);}const queryTheme=new URLSearchParams(location.search).get('theme');if(queryTheme==='dark'||queryTheme==='light')setTheme(queryTheme,false);window.scrollTo(0,0);const route=path.split('?')[0].replace(/\/$/,'')||'/';setMeta(route);
    app.setAttribute('aria-busy','true');try { if(route==='/') {await Promise.allSettled([loadOverview(),loadAlerts()]);try{const m=await GeoAPI.get('/api/metrics');state.metrics=m.metrics||[];updateDemo(m.demo??state.demo);}catch(_){}renderDashboard();}
      else if(route.startsWith('/ward/')) await renderWard(decodeURIComponent(route.slice(6)));
      else if(route==='/alerts') await renderAlerts();else if(route==='/metrics')await renderMetrics();else if(route==='/data')await renderData();else if(route==='/settings')await renderSettings();else if(route==='/how')renderHow();else renderNotFound();
    } catch(e) {app.innerHTML=`<div class="data-notice" role="alert">This view could not load: ${esc(e.message)} <button class="btn btn-small" type="button" data-action="retry">Retry</button></div>`;} finally {app.setAttribute('aria-busy','false');$('#main-content').focus({preventScroll:true});}
  }
  function renderNotFound(){app.innerHTML='<div class="empty-state">Page not found. <a href="/" data-route="/">Return to overview</a></div>';}
  function paramsFromForm(form){const data=new FormData(form);return Object.fromEntries([...data.entries()].map(([k,v])=>[k,k==='split_ratio'?Number(v):k==='folds'||k==='seed'?Number(v):v]));}
  async function submitThresholds(form){const body=paramsFromForm(form);const result=await GeoAPI.put('/api/settings/thresholds',body);state.thresholds=result.thresholds||result;toast('Thresholds saved. Existing classifications were submitted for reclassification.','success');return result;}
  async function runPipeline(button,type){if(type==='java'&&!confirm('This is a legacy 5 km fallback, not the canonical Python ROI. Continue?'))return;const names={raster:'raster',java:'java',dataset:'dataset',model:'train_and_predict'};const endpoints={raster:'/api/pipeline/raster',java:'/api/pipeline/java',dataset:'/api/pipeline/dataset',model:'/api/pipeline/model'};const job=await actionRun(button,async()=>{const check=await GeoAPI.get(`/api/pipeline/preflight/${names[type]}`);(check.checks||[]).forEach(item=>logLine(`${item.ok?'READY':'BLOCKED'} · ${item.name}: ${item.detail}`,item.ok?'success':'warning'));if(!check.ok)throw new Error(`Preflight blocked: ${(check.checks||[]).filter(x=>!x.ok).map(x=>`${x.name}: ${x.detail}`).join(' | ')}`);return GeoAPI.post(endpoints[type],{});},`${type==='java'?'Legacy Java':type==='model'?'Model':'Pipeline'} job submitted.`);const id=job?.job_id||job?.id;if(id)watchJob(id);}
  function logLine(text,kind=''){const consoleEl=$('#pipeline-console');if(!consoleEl)return;const line=document.createElement('div');line.className=`console-line ${kind?`console-${kind}`:''}`;line.textContent=`${new Date().toLocaleTimeString()} · ${text}`;consoleEl.append(line);consoleEl.scrollTop=consoleEl.scrollHeight;}
  function watchJob(id){logLine(`Job ${id} queued; connecting to live event stream.`);if(window.EventSource){const source=new EventSource(`/api/pipeline/jobs/${encodeURIComponent(id)}/events`);let terminal=false;source.onmessage=e=>{try{const x=JSON.parse(e.data);const text=x.timestamp?`[${x.timestamp}] ${x.stream||'log'}: ${x.message||''}`:x.message||x.log||JSON.stringify(x);logLine(text,x.stream==='error'?'error':'');}catch(_){logLine(e.data)}};source.addEventListener('status',e=>{try{const x=JSON.parse(e.data),status=x.status||x.state||'completed';terminal=['success','failed','cancelled','error'].includes(status);logLine(`Job ${id} ${status}${x.error?`: ${x.error}`:''}`,status==='failed'||status==='error'?'error':'success');if(terminal){source.close();toast(`Job ${id}: ${status}`,status==='failed'||status==='error'?'error':'success');}}catch(_){logLine(`Job ${id} finished.`,'success');source.close();}});source.addEventListener('error',e=>{if(e.data){try{logLine(JSON.parse(e.data).detail||e.data,'error');}catch(_){logLine(e.data,'error');}}});source.onerror=()=>{source.close();if(!terminal){logLine('Live event stream ended; checking job status by polling.','warning');pollJob(id);}};}else pollJob(id);}
  async function pollJob(id){let count=0;const timer=setInterval(async()=>{try{const payload=await GeoAPI.get(`/api/pipeline/jobs/${encodeURIComponent(id)}`);const j=payload.job||payload,status=j.status||j.state||'unknown';logLine(j.message||`Job ${id}: ${status}${j.error?` · ${j.error}`:''}`,status==='failed'||status==='error'?'error':status==='success'?'success':'');if(['success','failed','cancelled','error'].includes(status)||++count>50){clearInterval(timer);if(['success','failed','cancelled','error'].includes(status))toast(`Job ${id}: ${status}`,status==='failed'||status==='error'?'error':'success');}}catch(e){logLine(`Status check failed: ${e.message}`,'error');clearInterval(timer);}},2000);}
  async function searchMap(){const q=$('#ward-search')?.value.trim().toLowerCase();if(!q){toast('Enter a ward name, ward ID, or edge ID.','info');return;}const ward=state.wards.find(item=>String(item.ward_id).toLowerCase()===q||String(item.name).toLowerCase().includes(q));if(ward){GeoMap?.zoomWard(ward.ward_id);navigate(`/ward/${encodeURIComponent(ward.ward_id)}`);return;}try{const result=await GeoAPI.get('/api/edges?limit=10000');const edge=(result.edges||[]).find(item=>String(item.edge_id).toLowerCase().includes(q));if(edge){navigate(`/ward/${encodeURIComponent(edge.ward_id)}?edge=${encodeURIComponent(edge.edge_id)}`);return;}toast('No matching ward or edge ID was found.','error');}catch(error){toast(`Edge search unavailable: ${error.message}`,'error');}}
  async function handleClick(e) {
    const routeLink=e.target.closest('a[data-route]');if(routeLink){e.preventDefault();navigate(routeLink.dataset.route);return;}
    const toggle=e.target.closest('#theme-toggle');if(toggle){const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';setTheme(theme);return;}
    const layer=e.target.closest('[data-layer]');if(layer){document.querySelectorAll('[data-layer]').forEach(b=>b.setAttribute('aria-pressed',String(b===layer)));const mode=$('#map-mode');if(layer.dataset.layer==='Street-level'){if(mode){mode.value='street';mode.dispatchEvent(new Event('change',{bubbles:true}));}else GeoMap?.setLayer('Street-level');}else{if(mode)mode.value='ward';GeoMap?.setLayer(layer.dataset.layer);}return;}
    const kpi=e.target.closest('[data-kpi]');if(kpi){if(kpi.dataset.kpi==='alerts'){navigate('/alerts?status=open');return;}if(kpi.dataset.kpi==='metrics'){navigate('/metrics');return;}if(kpi.dataset.kpi==='refresh'){await actionRun(kpi,async()=>{await GeoAPI.post('/api/refresh',{});await Promise.allSettled([loadOverview(),loadAlerts()]);await navigate('/',false);},'Data refreshed.');return;}const filt=kpi.dataset.kpi==='critical'?'critical':kpi.dataset.kpi==='all'?'all':'all';const sel=$('#ward-filter');if(sel){sel.value=filt;$('#ward-register')?.scrollIntoView({behavior:'smooth'});const tbody=app.querySelector('.table-wrap tbody');if(tbody)tbody.innerHTML=wardRows(filt);GeoMap?.filterRisk(filt);}return;}
    const open=e.target.closest('[data-open-ward]');if(open){navigate(`/ward/${encodeURIComponent(open.dataset.openWard)}`);return;}
    const mapOpen=e.target.closest('[data-map-open]');if(mapOpen){navigate(`/ward/${encodeURIComponent(mapOpen.dataset.mapOpen)}`);return;}
    const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;
    if(action==='refresh'){await actionRun(b,async()=>{await GeoAPI.post('/api/refresh',{});await Promise.allSettled([loadOverview(),loadAlerts()]);await navigate(location.pathname,false);},'Data refreshed.');}
    else if(action==='export-csv'||action==='export-alerts'){const alerts=action==='export-alerts';await actionRun(b,()=>GeoAPI.download(alerts?'/api/export/csv?scope=alerts':'/api/export/csv',alerts?'geocool-alerts.csv':'geocool-edges.csv'),`${alerts?'Alerts':'CSV'} export downloaded.`);}
    else if(action==='export-pdf'){await actionRun(b,()=>GeoAPI.download('/api/export/pdf','geocool-report.pdf'),'PDF export downloaded.');}
    else if(action==='simulate'){const ward=$('#simulate-ward')?.value;const threshold=Number($('#simulate-threshold')?.value||40);await actionRun(b,async()=>{await GeoAPI.post('/api/alerts/simulate',{ward_id:ward,temperature:threshold});await loadAlerts();renderAlertTable();},'Synthetic threshold breach submitted.');}
    else if(action==='alert-status'){await actionRun(b,async()=>{await GeoAPI.patch(`/api/alerts/${encodeURIComponent(b.dataset.id)}`,{status:b.dataset.status});await loadAlerts();renderAlertTable();},`Alert ${b.dataset.status==='ack'?'acknowledged':'resolved'}.`);}
    else if(action==='ward-alert-status'){const ids=state.alerts.filter(a=>String(a.ward_id)===b.dataset.id&&!['resolved','closed'].includes(String(a.status).toLowerCase()));if(!ids.length){toast('No active alert for this ward. Open Alerts to simulate a demo breach.','info');return;}await actionRun(b,async()=>{await Promise.all(ids.map(a=>GeoAPI.patch(`/api/alerts/${encodeURIComponent(a.id)}`,{status:b.dataset.status})));await loadAlerts();},`Ward alert ${b.dataset.status==='ack'?'acknowledged':'resolved'}.`);}
    else if(action==='search-map'){await searchMap();}
    else if(action==='zoom-ward'){const id=b.dataset.id;await navigate('/',false);const ok=GeoMap?.zoomWard(id);toast(ok?'Map zoomed to ward.':'Map is unavailable because Leaflet did not load.','info');}
    else if(action==='view-streets'){const id=b.dataset.id;const data=await GeoAPI.get(`/api/wards/${encodeURIComponent(id)}/streets`);const edges=data.edges||data.streets||data;await navigate('/',false);GeoMap?.showStreets(edges);document.querySelector('#map-mode').value='street';toast(`${edges.length||0} street edges loaded on the overview map.`,'success');}
    else if(action==='sensor-history'){const data=await GeoAPI.get(`/api/wards/${encodeURIComponent(b.dataset.id)}/sensor-history`);const n=(data.history||data.readings||data).length||0;const chart=$('#ward-history-chart');chart?.scrollIntoView({behavior:'smooth',block:'center'});toast(`${n} history records returned${n?' and shown in the ward trend chart.':'.'}`,'success');}
    else if(action==='contrast-audit'){if(window.runContrastAudit)runContrastAudit();else toast('Contrast audit script is unavailable.','error');}
    else if(action==='pipeline')await runPipeline(b,b.dataset.pipeline);
    else if(action==='health-check')await actionRun(b,async()=>{const h=await GeoAPI.get('/api/health');toast(`API responded; database ${h.database?.connected?'connected':'status unknown'}.`,'success');},'Health check complete.');
    else if(action==='train-model'||action==='experiment'||action==='predict'){const form=$('#experiment-form');const values=form?paramsFromForm(form):{};const path=action==='train-model'?'/api/model/train':action==='experiment'?'/api/model/experiment':'/api/model/predict';const result=await actionRun(b,()=>GeoAPI.post(path,values),'Model request completed.');if(result)await navigate(location.pathname,false);}
    else if(action==='compare-runs'){const chosen=[...document.querySelectorAll('.run-compare:checked')];const out=$('#run-comparison');if(chosen.length<2){toast('Select at least two runs to compare.','error');return;}const runIds=chosen.map(x=>x.value);const found=state.runs.filter((r,i)=>runIds.includes(String(r.id||r.run_id||i)));out.innerHTML=table(['Run','Algorithm','Accuracy','Precision','Recall','F1','RMSE','MAE','R²'],found.map(r=>`<tr>${['id','algo','accuracy','precision','recall','f1','rmse','mae','r2'].map((k,i)=>`<td>${i===0?esc(r.id||r.run_id||'—'):i===1?esc(r.algo||r.algorithm||'—'):r[k]==null?'—':showVal(r[k],3)}</td>`).join('')}</tr>`));}
    else if(action==='retry')navigate(location.pathname,false);
  }
  async function toggleDemoMode(enabled){try{await GeoAPI.put('/api/settings/demo-mode',{enabled});localStorage.setItem('geocoolDemoPreference',String(enabled));toast(`Demo Mode preference saved. Synthetic records remain labeled DEMO DATA; the setting does not convert them to measured data.`,'success');}catch(error){toast(`Demo Mode setting could not be saved (${error.message}). Synthetic records remain labeled DEMO DATA.`,'error');}const toggle=$('#demo-mode-toggle');if(toggle)toggle.checked=enabled;}
  function setTheme(theme,persist=true){document.documentElement.dataset.theme=theme;if(persist)localStorage.setItem('geocoolTheme',theme);const b=$('#theme-toggle');if(b)b.setAttribute('aria-label',theme==='dark'?'Switch to light mode':'Switch to dark mode');const choice=$('#theme-choice');if(choice)choice.value=theme;}
  async function onSubmit(e){if(e.target.id==='threshold-form'){e.preventDefault();const b=e.target.querySelector('button[type="submit"]');await actionRun(b,()=>submitThresholds(e.target),'Thresholds saved.');}else if(e.target.id==='experiment-form'&&e.submitter?.dataset.action==='train-model'){e.preventDefault();const values=paramsFromForm(e.target);await actionRun(e.submitter,()=>GeoAPI.post('/api/model/train',values),'Training request accepted.');}}
  function onChange(e){if(e.target.matches('.threshold-range')){$(`#out-${e.target.name}`).textContent=num(e.target.value,2);}if(e.target.id==='theme-choice')setTheme(e.target.value);if(e.target.id==='demo-mode-toggle')toggleDemoMode(e.target.checked);if(e.target.id==='refresh-interval'){localStorage.setItem('geocoolRefresh',e.target.value);if(state.pollTimer)clearInterval(state.pollTimer);const n=Number(e.target.value);if(n)state.pollTimer=setInterval(async()=>{try{await GeoAPI.post('/api/refresh',{});if(location.pathname==='/')await navigate('/',false);else toast('Scheduled refresh completed.','success');}catch(err){toast(`Scheduled refresh failed: ${err.message}`,'error');}},n*60000);toast('Refresh preference saved on this device.','success');}if(e.target.id==='map-mode'){if(e.target.value==='street'){GeoMap?.setLayer('Street-level').catch(err=>toast(`Street layer unavailable: ${err.message}`,'error'));}else{const filter=$('#ward-filter')?.value||'all';GeoMap?.filterRisk(filter);GeoMap?.setLayer('Risk Class');document.querySelectorAll('[data-layer]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.layer==='Risk Class')));}}if(e.target.matches('#alert-ward-filter,#alert-class-filter,#alert-status-filter,#alert-time-filter'))renderAlertTable();if(e.target.id==='ward-filter'){const tbody=app.querySelector('.table-wrap tbody');if(tbody)tbody.innerHTML=wardRows(e.target.value);}}
  function init(){if(!app)return;if(!window.Chart){const n=document.createElement('div');n.className='data-notice';n.setAttribute('role','status');n.textContent='Chart.js could not load from its CDN. Numeric data and other page controls remain available; charts are omitted.';$('#demo-notice').after(n);}const initialTheme=new URLSearchParams(location.search).get('theme');setTheme(initialTheme==='dark'||initialTheme==='light'?initialTheme:(localStorage.getItem('geocoolTheme')||'light'),!initialTheme);document.addEventListener('click',e=>handleClick(e).catch(error=>toast(error.message||'Action failed.','error')));document.addEventListener('submit',onSubmit);document.addEventListener('change',onChange);window.addEventListener('popstate',()=>navigate(location.pathname,false));document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='ward-search')$('#main-content')?.querySelector('[data-action="search-map"]')?.click();if(e.key==='Escape'){document.activeElement?.blur();}});const aliases={'/dashboard.html':'/','/ward.html':'/','/alerts.html':'/alerts','/metrics.html':'/metrics','/data.html':'/data','/settings.html':'/settings','/how.html':'/how'};const initial=aliases[location.pathname]||location.pathname;if(aliases[location.pathname])history.replaceState({},'',initial);navigate(initial,false);}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();
